import type { V8PublicationState } from "./v8-shared";

export type V8Project = {
  slug: string;
  title: string;
  category: string;
  region: "Andhra Pradesh" | "Telangana" | "Other / confirm";
  location: string;
  role: string;
  scope: string[];
  state: V8PublicationState;
  summary: string;
  image: string;
  poster: string;
  placeholder: boolean;
  evidence: string;
  featured: boolean;
};

