export const MIROR_V8_RESERVED_PROJECTS: V8Project[] = Array.from({ length: 16 }, (_, offset) => {
  const number = offset + 3;
  return {
    slug: `client-project-${String(number).padStart(2, "0")}`,
    title: `Project ${String(number).padStart(2, "0")} — Details Pending`,
    category: "Client supplied",
    region: "Other / confirm",
    location: "Update soon",
    role: "Update soon",
    scope: ["Update scope"],
    state: "client-supplied",
    summary: "Reserved record for one of the client’s additional projects. Replace with approved information before publication.",
    image: "/media/projects/placeholder.jpg",
    poster: "/media/projects/placeholder-poster.jpg",
    placeholder: true,
    evidence: "Client project data sheet required.",
    featured: false,
  };
});

export const ALL_MIROR_V8_PROJECTS = [...MIROR_V8_PROJECTS, ...MIROR_V8_RESERVED_PROJECTS];

export function findMirorV8Project(slug: string) {
  return ALL_MIROR_V8_PROJECTS.find((project) => project.slug === slug) ?? null;
}

export function filterMirorV8Projects(query: string) {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return ALL_MIROR_V8_PROJECTS;
  return ALL_MIROR_V8_PROJECTS.filter((project) => [project.title, project.category, project.region, project.location, project.role, ...project.scope].join(" ").toLowerCase().includes(normalized));
}

